package main

import (
	"html/template"
	"net/url"
)

var adminTemplate = template.Must(template.New("admin").Funcs(template.FuncMap{
	"urlquery": url.QueryEscape,
	"t": t,
	"tf": tf,
	"lang": currentLang,
}).Parse(`<!doctype html>
<html lang="{{lang}}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{t "app.title"}}</title>
<style>
:root{--bg:#fff;--text:#222;--sub:#6b6b6b;--line:#e9e9e7;--soft:#f7f7f5;--danger:#b42318;--warn:#8a6500}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:"Segoe UI","Yu Gothic UI",sans-serif}.wrap{max-width:1040px;margin:0 auto;padding:42px 28px 132px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding-bottom:28px;border-bottom:1px solid var(--line)}h1{font-size:34px;letter-spacing:-.03em;margin:0 0 8px}.lead{color:var(--sub);font-size:15px;line-height:1.7;margin:0}.badge{font-size:12px;font-weight:700;background:var(--soft);padding:6px 9px;border-radius:6px;color:#555}.notice{margin-top:18px;padding:12px 14px;background:var(--soft);border-radius:8px;color:#555;font-size:14px}.idleWarn{display:none;margin-top:14px;padding:11px 13px;border:1px solid #e6d48d;background:#fffdf2;color:var(--warn);border-radius:7px;font-size:14px}.testHint{background:#fff7e6;border:1px solid #efcf8c;padding:11px 13px;border-radius:7px;font-size:14px;margin-top:14px}.group{padding:30px 0;border-bottom:1px solid var(--line)}.groupTitle{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:16px}.groupTitle h2{font-size:20px;margin:0}.groupTitle p{margin:0;color:var(--sub);font-size:13px}.prepGrid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.prep{border:1px solid var(--line);border-radius:9px;padding:20px;background:#fff}.prepHead{display:flex;gap:12px;align-items:flex-start;margin-bottom:18px}.stepNo{width:34px;height:34px;display:grid;place-items:center;flex:0 0 34px;border-radius:7px;background:#222;color:#fff;font-size:17px;font-weight:750}.prep h3{font-size:18px;margin:3px 0 4px}.prep p{margin:0;color:var(--sub);font-size:13px;line-height:1.6}.prepBody{display:grid;grid-template-columns:180px 1fr;gap:18px;align-items:start}.qr{width:180px;height:180px;border:1px solid #ddd;padding:7px;background:#fff}.label{font-size:12px;color:var(--sub);margin-bottom:4px}.value{font-size:16px;font-weight:650;overflow-wrap:anywhere}.mono{font-family:Consolas,"SFMono-Regular",monospace}.details{margin-top:12px}.details summary{cursor:pointer;color:#555;font-size:13px}.url{font-size:12px;overflow-wrap:anywhere;color:#555;margin-top:6px}.transfer{padding:32px 0}.transferHead{display:flex;gap:14px;align-items:flex-start;margin-bottom:20px}.transferNo{width:42px;height:42px;display:grid;place-items:center;flex:0 0 42px;border-radius:8px;background:#222;color:#fff;font-size:20px;font-weight:750}.transferKicker{font-size:12px;font-weight:700;color:#777;margin-bottom:2px}.transfer h2{font-size:24px;margin:2px 0 5px}.transfer p{margin:0;color:var(--sub);font-size:14px;line-height:1.7}.actions{display:flex;flex-wrap:wrap;gap:9px}.btn,.fileLabel{display:inline-flex;align-items:center;justify-content:center;border:1px solid #d7d7d7;background:#fff;color:#222;border-radius:7px;padding:10px 14px;font-size:14px;font-weight:650;cursor:pointer}.primary{background:#222;color:#fff;border-color:#222}.danger{color:var(--danger);border-color:#e5c4c0}.fileLabel input{display:none}.panels{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin-top:24px}.panel{min-width:0}.panel h3{font-size:16px;margin:0 0 5px}.muted{color:var(--sub);font-size:13px}.file{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}.file span:first-child{flex:1;min-width:0;overflow-wrap:anywhere}.status{font-size:14px;color:var(--sub);margin-top:10px}.ok{color:#2b7a3d}.finishBar{position:fixed;left:0;right:0;bottom:0;z-index:20;border-top:1px solid var(--line);background:rgba(255,255,255,.97)}.finishInner{max-width:1040px;margin:0 auto;padding:13px 28px;display:flex;align-items:center;justify-content:space-between;gap:20px}.finishText{font-size:13px;color:var(--sub)}.finishBtn{background:#222;color:#fff;border:1px solid #222;border-radius:7px;padding:10px 16px;font-size:14px;font-weight:700;cursor:pointer;white-space:nowrap}.expired{max-width:680px;margin:80px auto;padding:24px;color:#333}.expired h1{font-size:28px}@media(max-width:860px){.prepGrid{grid-template-columns:1fr}.prepBody{grid-template-columns:180px 1fr}}@media(max-width:620px){.wrap{padding:28px 18px 126px}.top,.groupTitle{flex-direction:column}.prep{padding:17px}.prepBody{grid-template-columns:1fr}.qr{width:200px;height:200px}.panels{grid-template-columns:1fr}.actions{display:grid;grid-template-columns:1fr}.btn,.fileLabel{width:100%}.finishInner{padding:10px 18px}.finishText{display:none}.finishBtn{width:100%;padding:12px 16px}}
</style></head><body><main class="wrap">
<div class="top"><div><h1>{{t "app.title"}}</h1><p class="lead">{{tf "app.deviceLead" .DeviceName}}</p></div>{{if .TestMode}}<div class="badge">{{t "app.testMode"}}</div>{{end}}</div>
<div class="notice">{{t "app.autoStopNotice"}}</div><div id="idleWarn" class="idleWarn">{{t "app.expiryWarning"}}</div>
{{if .TestMode}}<div class="testHint">{{t "app.testHint"}}</div>{{end}}
<section class="group"><div class="groupTitle"><h2>{{t "prep.label"}}</h2><p>{{t "prep.description"}}</p></div><div class="prepGrid">
<div class="prep"><div class="prepHead"><div class="stepNo">1</div><div><h3>{{t "step1.title"}}</h3><p>{{if .TestMode}}{{t "step1.testDescription"}}{{else}}{{t "step1.description"}}{{end}}</p></div></div>{{if .WiFiQR}}<div class="prepBody"><img class="qr" src="/qr.svg?text={{urlquery .WiFiQR}}" alt="QR"><div><div class="label">{{t "wifi.name"}}</div><div class="value">{{.WiFiSSID}}</div><div style="height:14px"></div><div class="label">{{t "wifi.password"}}</div><div class="value mono">{{.WiFiPassword}}</div><div class="muted" style="margin-top:10px">{{t "wifi.noInternet"}}</div></div></div>{{else}}<div class="muted">{{t "wifi.notUsed"}}</div>{{end}}</div>
<div class="prep"><div class="prepHead"><div class="stepNo">2</div><div><h3>{{t "step2.title"}}</h3><p>{{if .TestMode}}{{t "step2.testDescription"}}{{else}}{{t "step2.description"}}{{end}}</p></div></div>{{range $i,$u := .URLs}}{{if eq $i 0}}<div class="prepBody"><img class="qr" src="/qr.svg?text={{urlquery $u.URL}}" alt="QR"><div><div class="label">{{t "transfer.page"}}</div><div class="url">{{$u.URL}}</div><details class="details"><summary>{{t "transfer.connectionInfo"}}</summary><div class="muted" style="margin-top:8px">{{$u.Interface}} / {{$u.IP}}</div></details></div></div>{{end}}{{else}}<div class="muted">{{t "transfer.networkMissing"}}</div>{{end}}</div>
</div></section>
<section class="transfer"><div class="transferHead"><div class="transferNo">3</div><div><div class="transferKicker">{{t "step3.kicker"}}</div><h2>{{t "step3.title"}}</h2><p>{{t "step3.description"}}</p></div></div><div class="actions"><label class="fileLabel primary">{{t "admin.pickFiles"}}<input id="sharePick" type="file" multiple></label><button class="btn" onclick="openFolder('send')">{{t "admin.openSend"}}</button><button class="btn" onclick="openFolder('receive')">{{t "admin.openReceive"}}</button></div><div id="shareStatus" class="status"></div><div class="panels"><div class="panel"><h3>{{t "admin.sendHeading"}}</h3><div class="muted">{{t "admin.sendDescription"}}</div><div id="sendList"></div><button class="btn danger" onclick="clearSide('send')" style="margin-top:12px">{{t "admin.clearSend"}}</button></div><div class="panel"><h3>{{t "admin.receiveHeading"}}</h3><div class="muted">{{t "admin.receiveDescription"}}</div><div id="recvList"></div><button class="btn danger" onclick="clearSide('receive')" style="margin-top:12px">{{t "admin.clearReceive"}}</button></div></div></section>
</main><div class="finishBar"><div class="finishInner"><div class="finishText">{{t "finish.prompt"}}</div><button class="finishBtn" onclick="stopApp()">{{t "finish.button"}}</button></div></div><script>
const admin='/admin/{{.AdminToken}}';let allowClose=false;window.addEventListener('beforeunload',e=>{if(!allowClose){e.preventDefault();e.returnValue=''}});
const msg={preparing:{{t "admin.preparing"}},shareReady:{{t "admin.shareReady"}},confirmClearSend:{{t "admin.confirmClearSend"}},confirmClearReceive:{{t "admin.confirmClearReceive"}},emptySend:{{t "admin.emptySend"}},emptyReceive:{{t "admin.emptyReceive"}},finishConfirm:{{t "finish.confirm"}},finishDoneTitle:{{t "finish.doneTitle"}},finishDoneBody:{{t "finish.doneBody"}},timeoutBody:{{t "finish.timeoutBody"}}};
function fmt(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';if(n<1073741824)return(n/1048576).toFixed(1)+' MB';return(n/1073741824).toFixed(2)+' GB'}
document.getElementById('sharePick').addEventListener('change',async e=>{const st=document.getElementById('shareStatus');for(const f of e.target.files){st.textContent=msg.preparing+f.name;await rawUpload(f)}st.textContent=msg.shareReady;st.className='status ok';e.target.value='';loadStatus()});
function rawUpload(f){return new Promise(res=>{const x=new XMLHttpRequest();x.open('POST',admin+'/upload?name='+encodeURIComponent(f.name));x.onload=()=>res();x.onerror=()=>res();x.send(f)})}
async function openFolder(which){await fetch(admin+'/open?which='+which,{method:'POST'})}
async function clearSide(which){if(!confirm(which==='send'?msg.confirmClearSend:msg.confirmClearReceive))return;await fetch(admin+'/clear-'+which,{method:'POST'});loadStatus()}
async function loadStatus(){try{const r=await fetch(admin+'/api/status',{cache:'no-store'});if(!r.ok)throw 0;const s=await r.json();render('sendList',s.send,msg.emptySend);render('recvList',s.receive,msg.emptyReceive);const idle=Number(s.idleRemainingSec||0),absolute=Number(s.absoluteRemainingSec||0),remain=Math.min(idle,absolute),warn=document.getElementById('idleWarn');warn.style.display=remain>0&&remain<=600?'block':'none';if(remain<=0){allowClose=true;showDone(msg.timeoutBody)}}catch(e){}}
function render(id,fs,empty){const el=document.getElementById(id);if(!fs.length){el.innerHTML='<div class="muted" style="padding:10px 0"></div>';el.firstChild.textContent=empty;return}el.innerHTML='';for(const f of fs){const d=document.createElement('div');d.className='file';const n=document.createElement('span');n.textContent=f.name;const z=document.createElement('span');z.className='muted';z.textContent=fmt(f.size);d.append(n,z);el.appendChild(d)}}
function showDone(body){document.body.innerHTML='<div class="expired"><h1></h1><p></p></div>';document.querySelector('.expired h1').textContent=msg.finishDoneTitle;document.querySelector('.expired p').textContent=body}
async function stopApp(){if(!confirm(msg.finishConfirm))return;allowClose=true;await fetch(admin+'/stop',{method:'POST'});showDone(msg.finishDoneBody)}
loadStatus();setInterval(loadStatus,5000);
</script></body></html>`))
